/** Owns asynchronous projection creation and disposal for DOM-backed surfaces. */
export const createWebProjectionSurfaces = (options = {}) => {
    const entries = new Map();
    let stopped = false;
    const values = () => [...entries.values()].flatMap((entry) => (entry.surface ? [entry.surface] : []));
    let doc;
    let listeners;
    let motionFrame = 0;
    const invalidate = () => values().forEach((surface) => surface.invalidate());
    const changed = (owner) => values().forEach((surface) => surface.changed(owner));
    const observe = (owner) => {
        const ownerDocument = owner.nodeType === 9 ? owner : owner.ownerDocument;
        if (doc && doc !== ownerDocument)
            throw new TypeError('Projection surfaces must share one Document');
        if (doc)
            return;
        doc = ownerDocument;
        const win = doc.defaultView;
        listeners = new win.AbortController();
        const subscription = { signal: listeners.signal };
        win.addEventListener('resize', invalidate, subscription);
        win.addEventListener('orientationchange', invalidate, subscription);
        doc.addEventListener('visibilitychange', () => {
            if (doc.hidden)
                invalidate();
        }, subscription);
        const appearance = (event) => {
            const target = event.target instanceof win.Element ? event.target : undefined;
            if (target?.closest('style[data-native-ui-snapshot], [data-native-ui-projection-node]') || (target && options.ignoreTarget?.(target)))
                return;
            if (target?.hasAttribute('data-native-ui-snapshot') && event.pseudoElement)
                return;
            changed();
        };
        for (const name of ['load', 'transitionrun', 'transitionend', 'transitioncancel', 'animationstart', 'animationend', 'animationcancel'])
            doc.addEventListener(name, appearance, { ...subscription, capture: name === 'load' });
    };
    const followMotion = (moving, target = (source) => source) => {
        if (motionFrame || stopped || !moving.size || !doc?.defaultView)
            return;
        // Ancestor transforms already carry the image. Only the host's own motion needs rebasing.
        const surfaces = values().filter((surface) => (surface.token || surface.restoring) && surface.owners.some((owner) => moving.has(target(owner))));
        if (!surfaces.length)
            return;
        motionFrame = doc.defaultView.requestAnimationFrame(() => {
            motionFrame = 0;
            surfaces.forEach((surface) => surface.moved());
            followMotion(moving, target);
        });
    };
    const remove = async (owner) => {
        const entry = entries.get(owner);
        if (!entry)
            return;
        entries.delete(owner);
        if (entry.surface)
            await entry.surface.destroy();
        // A failed creation has nothing to dispose; ensure() reports that error.
        else
            await entry.ready.catch(() => { });
    };
    return {
        get: (owner) => entries.get(owner)?.surface,
        keys: () => entries.keys(),
        values,
        changed,
        invalidate,
        followMotion,
        end: () => values().forEach((surface) => surface.end()),
        consider: (...args) => values().forEach((surface) => surface.consider(...args)),
        updated: (...args) => values().forEach((surface) => surface.updated(...args)),
        get restoring() {
            return values().some((surface) => surface.restoring);
        },
        get handoffPending() {
            return values().some((surface) => surface.handoffPending);
        },
        ensure(owner, create) {
            if (stopped || !owner.isConnected)
                return Promise.resolve(undefined);
            observe(owner);
            const existing = entries.get(owner);
            if (existing)
                return existing.ready;
            const entry = {
                ready: Promise.resolve()
                    .then(create)
                    .then(async (surface) => {
                    if (stopped || entries.get(owner) !== entry || !owner.isConnected) {
                        if (entries.get(owner) === entry)
                            entries.delete(owner);
                        await surface.destroy();
                        return undefined;
                    }
                    entry.surface = surface;
                    return surface;
                })
                    .catch((error) => {
                    if (entries.get(owner) === entry)
                        entries.delete(owner);
                    throw error;
                }),
            };
            entries.set(owner, entry);
            return entry.ready;
        },
        delete: remove,
        async destroy() {
            stopped = true;
            listeners?.abort();
            if (motionFrame)
                doc?.defaultView?.cancelAnimationFrame(motionFrame);
            await Promise.all([...entries.keys()].map(remove));
        },
    };
};
